namespace RonSijm.FluidHumidifier.Factories.Transcribe;

public class MedicalScribeJobFactory(string resourceName = null, Action<Humidifier.Transcribe.MedicalScribeJob> factoryAction = null) : ResourceFactory<Humidifier.Transcribe.MedicalScribeJob>(resourceName)
{

    internal List<InnerMedicalScribeJobMedicalScribeChannelDefinitionFactory> ChannelDefinitionsFactories { get; set; } = [];

    internal InnerMedicalScribeJobMediaFactory MediaFactory { get; set; }

    internal InnerMedicalScribeJobMedicalScribeSettingsFactory SettingsFactory { get; set; }

    protected override Humidifier.Transcribe.MedicalScribeJob Create()
    {
        var medicalScribeJobResult = CreateMedicalScribeJob();
        factoryAction?.Invoke(medicalScribeJobResult);

        return medicalScribeJobResult;
    }

    private Humidifier.Transcribe.MedicalScribeJob CreateMedicalScribeJob()
    {
        var medicalScribeJobResult = new Humidifier.Transcribe.MedicalScribeJob
        {
            GivenName = InputResourceName,
        };

        return medicalScribeJobResult;
    }
    public override void CreateChildren(Humidifier.Transcribe.MedicalScribeJob result)
    {
        base.CreateChildren(result);

        result.ChannelDefinitions = ChannelDefinitionsFactories.Any() ? ChannelDefinitionsFactories.Select(x => x.Build()).ToList() : null;
        result.Media ??= MediaFactory?.Build();
        result.Settings ??= SettingsFactory?.Build();
    }

} // End Of Class

